fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let freqs = [262, 294, 330, 349, 392, 440, 494];
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut lastk: i32 = host::display::state_get(1);
    let mut glow: i32 = host::display::state_get(2);
    let kw: i32 = w / 7;
    let ktop: i32 = h - 180;
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if py >= ktop {
            let mut k: i32 = px / kw;
            if k > 6 { k = 6; }
            host::audio::tone(freqs[k], 300, 0);
            lastk = k;
            glow = 8;
        }
    }
    if glow > 0 { glow = glow - 1; }
    host::display::state_set(0, down);
    host::display::state_set(1, lastk);
    host::display::state_set(2, glow);
    host::display::clear(0x101010);
    let mut i: i32 = 0;
    while i < 7 {
        let mut c: i32 = 0xe8e8e8;
        if glow > 0 && i == lastk { c = 0x00c8ff; }
        host::display::fill_rect(i * kw + 2, ktop, kw - 4, 176, c);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "ONE OCTAVE", 0xffffff, 2);
    if glow > 0 {
        host::display::draw_number(8, 40, freqs[lastk], 0x00c8ff, 2);
    }
    host::display::present();
}
